def theme_tone(mulank,day):
    gap = min(abs(mulank-day),9-abs(mulank-day))
    return 0 if gap == 0 else 1 if gap == 1 else 2

def rotation_variant(dob,target,personal_day,variant_count=3):
    birth = dt.date.fromisoformat(dob)
    day = dt.date.fromisoformat(target)
    if day.year < 1900:
        raise ValueError('rotation supported from 1900')
    count = 0
    for year in range(1900,day.year+1):
        last_month = day.month if year == day.year else 12
        for month in range(1,last_month+1):
            if year == day.year and month == day.month:
                limit = day.day
            else:
                next_month = dt.date(year+1,1,1) if month == 12 else dt.date(year,month+1,1)
                limit = (next_month-dt.timedelta(days=1)).day
            base = birth.day+birth.month+year+month
            first = (personal_day-base-1)%9+1
            if first <= limit:
                count += (limit-first)//9+1
    return (count-1)%variant_count

