def digest_extras(profile,date,weather=None):
    # Existing date-rotated catalog, not AI-generated links.
    lang=profile['language']
    r=SHORT_READING[lang]
    day=numbers(profile['dob'],date)['values'][4]
    song_index = rotation_variant(profile['dob'],date,day,len(r['songs'][day-1]))
    pod_index = rotation_variant(profile['dob'],date,day,len(r['podcasts'][day-1]))
    category=weather['category'] if weather else None
    song = weather_media(lang,day,rotation_variant(profile['dob'],date,day,1000000),'songs',category,r['songs'][day-1][song_index])
    if not song[2]:
        linked=[x for pool in r['songs'] for x in pool if x[2] and (not (lang=='bn' and x[0]=='এসো হে বৈশাখ') or int(date[5:7]) in [4,5])]
        if linked:song=linked[media_seed(profile['dob'],date)%len(linked)]
    music = r['music']+song[0]+' - '+song[1]+(' '+song[2] if song[2] else '')
    pod = weather_media(lang,day,rotation_variant(profile['dob'],date,day,1000000),'podcasts',category,r['podcasts'][day-1][pod_index])
    if not pod[2]:
        linked=[x for pool in r['podcasts'] for x in pool if x[2]]
        if linked:pod=linked[media_seed(profile['dob'],date)%len(linked)]
    podcast = r['podcastLabel']+pod[0]+' - '+pod[1]+(' '+pod[2] if pod[2] else '')
    return [r['color']+r['colors'][day-1]+' | '+r['number']+(bn_digits(day) if lang=='bn' else str(day)),
            '',music if (dt.date.fromisoformat(date)-dt.date(1970,1,1)).days%2==0 else podcast]

def short_reading(profile,date,weather=None):
    return '\n'.join([greeting(profile),'',normal_note(profile,date,weather),'',*digest_extras(profile,date,weather)])

def render(profile,date,data=None,why=False,weather=None):
    if not why:
        return short_reading(profile,date,weather)
    lang=profile['language']
    n=numbers(profile['dob'],date)
    lines=['অ্যাস্ট্রোপালস | আজ আপনার জন্য কিছু কথা | '+bn_digits(date)+' | '+bn_timezone(profile['timezone']) if lang == 'bn' else 'AstroPulse | '+date+' | '+friendly_timezone(profile['timezone'])]
    for label,value,calc in zip(LABELS[lang],n['values'],n['traces']):
        lines.append(f"{label}: {bn_digits(value) if lang == 'bn' else value}"+(f" ({bn_digits(calc.replace(' -> ', ' → ')) if lang == 'bn' else calc})" if why else ''))
    lines+=['',bn_digits(personal_reading(n,lang)) if lang == 'bn' else personal_reading(n,lang),'',DISCLAIMER[lang]]
    if why: lines+=['','হিসাবের নিয়ম: যোগ করতে করতে শেষে ১ থেকে ৯-এর মধ্যে আনি। বছরের হিসাব জানুয়ারি থেকে ডিসেম্বর ধরে।'] if lang == 'bn' else ['',METHOD,'Calendar-year cycle; all results reduced to 1-9.']
    if data:
        lines+=['',INDIA_ONLY[lang], ('পঞ্চাঙ্গ | ' if lang == 'bn' else 'Panchang | ')+profile['location_label']]
        if lang == 'bn': lines+=bn_panchang(data)
        else:
            lines += [f"Tithi: {data['tithiNumber']} ({data.get('paksha','')})",'Nakshatra: '+str(data['nakshatra']),'Sunrise: '+str(data['sunrise'])+' | Sunset: '+str(data['sunset'])]
            if 'rahuKaal' in data:
                r=data['rahuKaal']; lines.append('Rahu Kaal: '+str(r.get('start','?'))+' - '+str(r.get('end','?')))
        lines+=[('সূত্র: ' if lang == 'bn' else 'Source: ')+'https://www.kundlidost.in/api/']
    elif not why:
        lines+=['',UNAVAILABLE[lang] if profile['panchang_india'] else INDIA_ONLY[lang]]
    return '\n'.join(lines)

